    for(var d=1;d<=5;d++){(function(d){var r=dayRec(S.g,w.n,d);var res=mem.results[dk(S.g,w.n,d)]||{};var names=Object.keys(res);var avg=names.length?(names.reduce(function(s,n){return s+res[n].best;},0)/names.length).toFixed(1):null;var c=el("button","dcell"+(r.taught?" t":r.best!==undefined?" d":r.viewed?" v":""),(r.taught?"Taught":r.best!==undefined?"Done":r.viewed?"Viewed":"Open")+(avg!==null?'<small>'+names.length+' students, avg '+avg+'/3</small>':r.best!==undefined?'<small>best '+r.best+'/3</small>':'<small>'+w.focus[d-1].split(" ").slice(0,4).join(" ")+'&hellip;</small>'));c.title=w.focus[d-1]+(r.updated?" (updated "+r.updated+")":"");c.addEventListener("click",function(){dayMenu(c,S.g,w.n,d,renderProgress);});var cell=el("td");cell.appendChild(c);tr.appendChild(cell);})(d);}
