/* ---- progress file (survives moving the app between folders or computers) ---- */
var FILE={handle:null,name:"",timer:null,supported:!!(window.showSaveFilePicker&&window.indexedDB)};
function idb(){return new Promise(function(res,rej){var r=indexedDB.open("lwmg-files",1);r.onupgradeneeded=function(){r.result.createObjectStore("kv");};r.onsuccess=function(){res(r.result);};r.onerror=function(){rej(r.error);};});}
function idbSet(k,v){return idb().then(function(db){return new Promise(function(res,rej){var t=db.transaction("kv","readwrite");t.objectStore("kv").put(v,k);t.oncomplete=function(){res();};t.onerror=function(){rej(t.error);};});});}
function idbGet(k){return idb().then(function(db){return new Promise(function(res,rej){var t=db.transaction("kv","readonly");var q=t.objectStore("kv").get(k);q.onsuccess=function(){res(q.result);};q.onerror=function(){rej(q.error);};});});}
function idbDel(k){return idb().then(function(db){return new Promise(function(res){var t=db.transaction("kv","readwrite");t.objectStore("kv").delete(k);t.oncomplete=function(){res();};});});}
function fileWrite(){if(!FILE.handle)return Promise.resolve();return FILE.handle.createWritable().then(function(w){return w.write(JSON.stringify(mem,null,1)).then(function(){return w.close();});}).then(function(){setFileStatus("Saved to "+FILE.name+" at "+new Date().toLocaleTimeString());}).catch(function(e){setFileStatus("Could not write "+FILE.name+": "+e.message,true);});}
function fileWriteSoon(){if(!FILE.handle)return;clearTimeout(FILE.timer);FILE.timer=setTimeout(fileWrite,600);}
function setFileStatus(t,bad){var n=document.getElementById("fileStatus");if(n){n.textContent=t;n.className="meta"+(bad?" warn":"");}}
function fileTypes(){return [{description:"Learning progress file",accept:{"application/json":[".json"]}}];}
function fileLinkNew(){if(!FILE.supported)return Promise.reject(new Error("unsupported"));return window.showSaveFilePicker({suggestedName:"learning-with-"+slug(teacher())+"-progress.json",types:fileTypes()}).then(function(h){FILE.handle=h;FILE.name=h.name;return idbSet("handle",h);}).then(fileWrite).then(function(){render();});}
function fileOpenExisting(){if(!FILE.supported)return Promise.reject(new Error("unsupported"));return window.showOpenFilePicker({types:fileTypes(),multiple:false}).then(function(hs){var h=hs[0];return h.requestPermission({mode:"readwrite"}).then(function(p){if(p!=="granted")throw new Error("permission not granted");FILE.handle=h;FILE.name=h.name;return idbSet("handle",h);}).then(function(){return h.getFile();}).then(function(f){return f.text();}).then(function(txt){var o=JSON.parse(txt);if(!(o&&o.days))throw new Error("not a progress file");adoptData(o);return fileWrite();}).then(function(){render();});});}
function fileReconnect(){if(!FILE.handle)return Promise.resolve();var h=FILE.handle;return h.queryPermission({mode:"readwrite"}).then(function(p){return p==="granted"?p:h.requestPermission({mode:"readwrite"});}).then(function(p){if(p!=="granted")throw new Error("permission not granted");return h.getFile();}).then(function(f){return f.text();}).then(function(txt){var o=null;try{o=JSON.parse(txt);}catch(e){}if(o&&o.days){if((o.updated||"")>(mem.updated||""))adoptData(o);else return fileWrite();}else return fileWrite();}).then(function(){FILE.pending=false;render();});}
function fileUnlink(){FILE.handle=null;FILE.name="";return idbDel("handle").then(function(){render();});}
function adoptData(o){for(var k in mem)if(o[k]!==undefined)mem[k]=o[k];mem.settings=mem.settings||{};mem.settings.teacher=mem.settings.teacher||"Mrs. Garcia";save(true);applySettings();}
function fileBanner(){var b=document.getElementById("banner");if(!b)return;if(FILE.pending&&FILE.handle){b.innerHTML='<span>Your progress file <b>'+esc(FILE.name)+'</b> is linked. Reconnect it to load the latest progress and keep saving to it.</span><button class="btn sm" id="reconnect">Reconnect</button><button class="btn quiet sm" id="notnow">Not now</button>';b.style.display="flex";b.querySelector("#reconnect").addEventListener("click",function(){fileReconnect().catch(function(e){setFileStatus("Reconnect failed: "+e.message,true);});b.style.display="none";});b.querySelector("#notnow").addEventListener("click",function(){FILE.pending=false;b.style.display="none";});}else b.style.display="none";}

/* ---- day actions: mark, unmark, clear ---- */
function dayMenu(anchor,g,w,d,after){var old=document.getElementById("daymenu");if(old&&old.parentNode)old.parentNode.removeChild(old);var r=dayRec(g,w,d);var res=mem.results[dk(g,w,d)]||{};var m=el("div","daymenu");m.id="daymenu";m.setAttribute("role","menu");
  m.innerHTML='<div class="meta" style="padding:.2rem .4rem">'+DATA[g].label+' &middot; Week '+w+' &middot; Day '+d+'</div><button class="mi" data-a="open">Open this lesson</button><button class="mi" data-a="taught">'+(r.taught?"Unmark as taught":"Mark as taught")+'</button>'+(r.best!==undefined||Object.keys(res).length?'<button class="mi" data-a="clear">Clear exit-ticket scores'+(Object.keys(res).length?' ('+Object.keys(res).length+' students)':'')+'</button>':'')+(r.viewed&&!r.taught&&r.best===undefined?'<button class="mi" data-a="reset">Reset to not started</button>':'')+'<div class="meta" style="padding:.2rem .4rem">Click outside or press Esc to dismiss.</div>';
  var rect=anchor.getBoundingClientRect();m.style.top=(rect.bottom+window.scrollY+4)+"px";m.style.left=Math.min(rect.left+window.scrollX,window.innerWidth-260)+"px";document.body.appendChild(m);
  Array.prototype.forEach.call(m.querySelectorAll(".mi"),function(b){b.addEventListener("click",function(){var a=b.getAttribute("data-a");if(a==="open"){S.g=g;S.w=w;S.d=d;S.view="teach";render();window.scrollTo(0,0);}
    if(a==="taught")setDay(g,w,d,{taught:r.taught?0:1});if(a==="clear"){var rec=mem.days[dk(g,w,d)]||{};delete rec.best;delete rec.attempts;mem.days[dk(g,w,d)]=rec;delete mem.results[dk(g,w,d)];save();}if(a==="reset"){delete mem.days[dk(g,w,d)];save();}
    m.parentNode.removeChild(m);if(a!=="open"&&after)after();});});
  setTimeout(function(){document.addEventListener("click",function h(e){if(!m.contains(e.target)){if(m.parentNode)m.parentNode.removeChild(m);document.removeEventListener("click",h);}});},0);
  document.addEventListener("keydown",function k(e){if(e.key==="Escape"){if(m.parentNode)m.parentNode.removeChild(m);document.removeEventListener("keydown",k);}});}

