function machinesForDay(g,w,d){var specs=DATA[g].weeks[w-1].days[d-1];var out=[];specs.forEach(function(sp){var keys=sp[0]==="bank"?(MACHINE_FOR.bank[sp[1].bank]||[]):(MACHINE_FOR[sp[0]]||[]);keys.forEach(function(k){if(out.indexOf(k)<0)out.push(k);});});if(!out.length)out.push(STRAND_MACHINE[DATA[g].weeks[w-1].icon]||"tenframe");return out;}
function machineNode(key){var def=MACHINES[key];var m=mframe(def.title,"grades "+def.grades);m.setAttribute("data-machine",key);def.build(m);m.pop.addEventListener("click",function(){popStudent("machine:"+key);});return m;}

/* ===== student window (share this window, not your screen) ===== */
function popStudent(mode){var base=location.href.split("#")[0];var url=base+"#student="+encodeURIComponent(mode)+"&g="+encodeURIComponent(S.g)+"&w="+S.w+"&d="+S.d+"&s="+encodeURIComponent(S.subj||"math");var win=window.open(url,"lwmg-student-"+mode.replace(/[^a-z0-9]/gi,""),"popup=yes,width=1280,height=820,resizable=yes,scrollbars=yes");if(!win){alert("The browser blocked the pop-up. Allow pop-ups for this page and try again.");return;}try{win.focus();}catch(e){}}
function parseStudentHash(){var h=(typeof location!=="undefined"&&location.hash)||"";var m=h.match(/#student=([^&]+)(?:&g=([^&]+))?(?:&w=(\d+))?(?:&d=(\d+))?(?:&s=([^&]+))?/);if(!m)return false;S.subj=m[5]?decodeURIComponent(m[5]):"math";S.studentMode=decodeURIComponent(m[1]);if(m[2]&&DATA[decodeURIComponent(m[2])])S.g=decodeURIComponent(m[2]);if(m[3])S.w=Math.max(1,Math.min(18,+m[3]));if(m[4])S.d=Math.max(1,Math.min(5,+m[4]));return true;}
function renderStudent(){document.body.className="student"+(S.studentMode==="lesson"?"":" projector");document.title=brand()+" - Student window";var g=DATA[S.g],w=g.weeks[S.w-1],specs=specsFor(S.g,S.w,S.d),pool=[].concat.apply([],w.days);document.documentElement.style.setProperty("--accent",g.color);
  var main=document.getElementById("main");main.innerHTML="";var top=el("div","stubar");top.innerHTML='<span class="ctxg" style="background:'+g.color+'">'+g.label+'</span><b>Week '+w.n+' &middot; Day '+S.d+'</b><span class="meta">'+w.unit+'</span><span class="meta" style="margin-left:auto">'+esc(brand())+' &middot; student window</span>';main.appendChild(top);
  var mode=S.studentMode;
  if(mode==="lesson"){if(S.subj!=="math")renderTeachSubj();else renderTeach();return;}
  if(mode==="live"&&S.subj!=="math"){var cw=subjWeek(S.subj,S.g,S.w);if(!cw){main.appendChild(el("div","card","<p>Standards not loaded.</p>"));return;}main.appendChild(deckView(buildConceptDeck(S.subj,S.g,S.w,S.d)));return;}
  if(mode==="live"){var hero=el("div","card hero");hero.innerHTML='<div><div class="eyebrow">'+g.label+' &middot; Week '+w.n+' &middot; Day '+S.d+'</div><h1>'+w.unit+'</h1><div class="ican">'+w.ican+'</div></div><div class="art">'+strandIcon(w.icon,84)+'</div>';main.appendChild(hero);main.appendChild(presenter(specs,pool));return;}
  if(mode==="machines"){var c=el("div","card");c.innerHTML='<h2>Machines: '+w.unit+'</h2>';machinesForDay(S.g,S.w,S.d).forEach(function(k){c.appendChild(machineNode(k));});main.appendChild(c);return;}
  if(mode.indexOf("machine:")===0){var key=mode.slice(8);var c2=el("div","card");if(MACHINES[key])c2.appendChild(machineNode(key));else c2.innerHTML='<p>Unknown machine.</p>';main.appendChild(c2);return;}
  main.appendChild(el("div","card","<p>Nothing to show. Close this window and open it again from the Teach or Activities view.</p>"));}

/* ===== TEKS chip popover ===== */
var RULE_SEC={K:"§111.2","1":"§111.3","2":"§111.4","3":"§111.5","4":"§111.6","5":"§111.7"};
function closest(node,sel){while(node&&node.nodeType===1){if(node.matches?node.matches(sel):false)return node;node=node.parentNode;}return null;}
function teksPop(chip){var old=document.getElementById("tekspop");if(old&&old.parentNode)old.parentNode.removeChild(old);var code=chip.getAttribute("data-code"),g=chip.getAttribute("data-g"),subj=chip.getAttribute("data-subj")||"math";var gd=DATA[g];if(!gd)return;var txt=subj==="math"?(gd.teks[code]||"Text not on file for this code."):stdSE(subj,g,code).text;var proc=subj==="math"?/\.1[A-G]$/.test(code):false;var weeks=subj==="math"?gd.weeks.filter(function(w){return w.teks.indexOf(code)>=0;}).map(function(w){return "Week "+w.n+" ("+w.unit+")";}):(subjYear(subj,g)||[]).filter(function(w){return w.codes.indexOf(code)>=0;}).map(function(w){return "Week "+w.n;});var sd=subjDef(subj);var std=stdFor(subj,g);
  var pop=el("div","daymenu tekspop");pop.id="tekspop";pop.setAttribute("role","dialog");pop.innerHTML='<div class="tag">TEKS '+code+' &middot; '+gd.label+' '+esc(sd.name)+' &middot; 19 TAC §'+esc(std?std.section:RULE_SEC[g].replace("§",""))+'</div><p class="tekstext">The student is expected to '+esc(txt)+'.</p>'+(proc?'<p class="meta">This is a mathematical process standard. It is integrated into every lesson and listed on a week only where it is the explicit teaching point.</p>':'')+'<p class="meta">Taught in: '+(weeks.length?weeks.join("; "):"not scheduled this semester")+'</p><div class="btn-row">'+(sd.pdf?'<a class="btn sm" href="'+sd.pdf+'" target="_blank" rel="noopener">Official rule text (TEA PDF)</a>':'')+'<a class="btn quiet sm" href="'+sd.index+'" target="_blank" rel="noopener">TEA Chapter '+sd.chapter+' index</a><a class="btn quiet sm" href="'+GRADE_PDF[g]+'" target="_blank" rel="noopener">All subjects, this grade (PDF)</a></div><div class="meta">Click outside or press Esc to close.</div>';
  var r=chip.getBoundingClientRect();pop.style.top=(r.bottom+window.scrollY+6)+"px";pop.style.left=Math.max(8,Math.min(r.left+window.scrollX,window.innerWidth-420))+"px";document.body.appendChild(pop);
  setTimeout(function(){document.addEventListener("click",function h(e){if(!pop.contains(e.target)){if(pop.parentNode)pop.parentNode.removeChild(pop);document.removeEventListener("click",h);}});},0);
  document.addEventListener("keydown",function k(e){if(e.key==="Escape"){if(pop.parentNode)pop.parentNode.removeChild(pop);document.removeEventListener("keydown",k);}});}
document.addEventListener("click",function(e){var c=closest(e.target,".chip[data-code]");if(c){e.preventDefault();teksPop(c);}});

/* ===== notes: many per week, each labeled General / a day / a student ===== */
function notesCell(g,wn,rs){var key=g+"-"+wn;var wrap=el("div","notes");
  function draw(){wrap.innerHTML="";var list=mem.notesList[key]||[];var ul=el("div","notelist");list.forEach(function(n){var it=el("div","noteit");it.innerHTML='<span class="nlabel">'+esc(n.label)+'</span><span class="ntext">'+esc(n.text)+'</span><span class="meta ndate">'+esc(n.date||"")+'</span><button class="ndel noprint" title="Delete this note" aria-label="Delete note">&times;</button>';it.querySelector(".ndel").addEventListener("click",function(){if(!confirm("Delete this note?"))return;mem.notesList[key]=list.filter(function(x){return x.id!==n.id;});save();draw();});ul.appendChild(it);});
    if(!list.length)ul.appendChild(el("div","meta printonly","No notes."));wrap.appendChild(ul);
    var add=el("button","btn quiet sm noprint","+ Add note");var form=el("div","noteform noprint");form.style.display="none";var opts=["General","Day 1","Day 2","Day 3","Day 4","Day 5"].concat(rs||[]);form.innerHTML='<label class="meta">About <select class="nsel">'+opts.map(function(o){return '<option>'+esc(o)+'</option>';}).join("")+'</select></label><textarea class="note ntxt" placeholder="Write the note"></textarea><div class="btn-row"><button class="btn sm nsave">Save note</button><button class="btn quiet sm ncancel">Cancel</button></div>';
    add.addEventListener("click",function(){form.style.display="";form.querySelector(".ntxt").focus();});form.querySelector(".ncancel").addEventListener("click",function(){form.style.display="none";});
    form.querySelector(".nsave").addEventListener("click",function(){var t=form.querySelector(".ntxt").value.trim();if(!t)return;(mem.notesList[key]=mem.notesList[key]||[]).push({id:Date.now()+Math.random(),label:form.querySelector(".nsel").value,text:t,date:today()});save();draw();});
    wrap.appendChild(add);wrap.appendChild(form);}
  draw();return wrap;}
function printHead(title){var h=el("div","printhead");h.innerHTML='<b>'+esc(brand())+(mem.settings.klass?' &middot; '+esc(mem.settings.klass):'')+'</b> &middot; '+esc(title)+' &middot; printed '+today();return h;}

