 longdiv:{name:"DMSB",say:"Does McDonald's Sell Burgers?",letters:[["D","Divide","How many times does the divisor fit? Write it on top."],["M","Multiply","Multiply that number by the divisor. Write it underneath."],["S","Subtract","Subtract. The leftover must be smaller than the divisor."],["B","Bring down","Bring down the next digit and start again at D."]],chant:"Divide, Multiply, Subtract, Bring down. Repeat until nothing is left to bring down.",check:"Check: quotient times divisor, plus remainder, equals the dividend."},
 oops:{name:"PEMDAS",say:"Please Excuse My Dear Aunt Sally",letters:[["P","Parentheses","Do what is inside ( ) first. Brackets [ ] are big parentheses: do them after."],["E","Exponents","Not yet in grade 5. Skip this step."],["MD","Multiply or Divide","Left to right, whichever comes first."],["AS","Add or Subtract","Left to right, whichever comes first."]],chant:"Parentheses, then multiply or divide, then add or subtract.",check:"Circle each step before you compute it."},
 round:{name:"Rounding rhyme",say:"Find the place, look next door.",letters:[["1","Find the place","Underline the digit in the place you are rounding to."],["2","Look next door","Look at the digit just to the right."],["3","5 or more? Add one more","If it is 5, 6, 7, 8, or 9, the underlined digit goes up by one."],["4","4 or less? Let it rest","If it is 0, 1, 2, 3, or 4, the underlined digit stays."],["5","Zeros fill the rest","Every digit to the right becomes 0."]],chant:"Find the place, look next door. 5 or more, add one more. 4 or less, let it rest. Zeros fill the rest.",check:"Is the answer a friendly number ending in zeros?"},
 wordproblem:{name:"CUBES",say:"CUBES for word problems",letters:[["C","Circle the numbers","Circle every number, including the ones written as words."],["U","Underline the question","Underline the sentence with the question mark."],["B","Box the key words","Box words that tell you what to do: in all, left, each, how many more."],["E","Evaluate","Decide: add, subtract, multiply, or divide? One step or two? Draw a strip diagram."],["S","Solve and check","Solve. Then ask: does this answer make sense in the story?"]],chant:"Circle, Underline, Box, Evaluate, Solve.",check:"Read the answer back into the story. Does it make sense?"},
 compare:{name:"The alligator",say:"The alligator eats the bigger number",letters:[["1","Line them up","Write the numbers one above the other by place value."],["2","Start on the left","Compare the biggest place first."],["3","Same? Move right","If the digits match, look at the next place to the right."],["4","Open mouth to the bigger","The symbol opens toward the bigger number: 9 > 4, 4 < 9."]],chant:"Line up, start left, open mouth to the bigger number.",check:"Read it aloud: 'nine is greater than four.'"},
 regroupAdd:{name:"Ten or more? Go next door.",say:"Add the ones. Ten or more? Go next door.",letters:[["1","Line up","Ones under ones, tens under tens."],["2","Add the ones","If the ones make 10 or more, regroup: write the ones digit, carry 1 ten next door."],["3","Add the tens","Include the ten you carried."],["4","Keep going","Hundreds next, the same way. Check with an estimate."]],chant:"Line up, add the ones, ten or more go next door.",check:"Estimate first. Is the answer close to the estimate?"},
 regroupSub:{name:"More on top? No need to stop.",say:"More on top, no need to stop. More on the floor, go next door.",letters:[["1","More on top? No need to stop","If the top digit is bigger, just subtract."],["2","More on the floor? Go next door","If the bottom digit is bigger, borrow a ten from the next place."],["3","Numbers the same? Zero's the game","If the digits match, write 0."],["4","Check by adding","Answer plus the number you subtracted should equal the top number."]],chant:"More on top, no need to stop. More on the floor, go next door. Numbers the same, zero's the game.",check:"Add back to check."},
 fraction:{name:"N-Up, D-Down",say:"Numerator is up, denominator is down",letters:[["N","Numerator","The top Number: how many pieces you have."],["D","Denominator","Down at the bottom: how many equal pieces in the whole."],["=","Equal parts","Every piece must be the same size, or it is not a fraction."]],chant:"Top tells how many, bottom tells the size.",check:"Count the pieces in the whole first, then the shaded ones."},
 fracsum:{name:"Same bottom, add the tops",say:"Same bottom? Add the tops. Different bottoms? Rename first.",letters:[["1","Look at the bottoms","Same denominator? Keep it and add or subtract the tops."],["2","Different? Rename","Find a common denominator: a number both bottoms go into."],["3","Whatever you do to the bottom, do to the top","Multiply top and bottom by the same number."],["4","Add or subtract the tops","The bottom stays. Simplify if you can."]],chant:"Same bottom, add the tops. Different bottoms, rename first.",check:"Are the pieces the same size before you add?"},
 fracequiv:{name:"Top and bottom together",say:"Whatever you do to the top, do to the bottom",letters:[["1","Pick a multiplier","Any whole number: 2, 3, 4..."],["2","Multiply the top","Numerator times the multiplier."],["3","Multiply the bottom","Denominator times the same multiplier."],["4","Same point","Both fractions land on the same point on the number line."]],chant:"Same number, top and bottom, same amount.",check:"Do the strips cover the same length?"},
 mult:{name:"Groups of",say:"Times means groups of",letters:[["1","Groups","How many groups? That is the first factor."],["2","In each","How many in each group? That is the second factor."],["3","Skip count","Count by the group size: 4, 8, 12..."],["4","Product","The total is the product."]],chant:"3 times 4 means 3 groups of 4.",check:"Draw the array. Rows times columns."},
