 pv:{name:"Say the place, say the value",say:"Ones, Tens, Hundreds: right to left",letters:[["1","Point to the digit","Which digit are we talking about?"],["2","Name the place","Start at the right: ones, tens, hundreds, thousands..."],["3","Say the value","Digit times the place: a 4 in the tens is 40."],["4","Ten times bigger","Move one place left and the value is ten times as much."]],chant:"Ones, tens, hundreds, thousands. Say the place, say the value.",check:"Write the number in expanded form and add it back."},
