 areaperim:{name:"RIM and INSIDE",say:"PeRIMeter goes around the rim. Area covers the inside.",letters:[["P","Perimeter","Add all the sides. Distance around."],["A","Area","Count the squares inside. Length times width."],["U","Units","Perimeter: units. Area: square units."]],chant:"Perimeter around, area inside.",check:"Did you add for perimeter and multiply for area?"},
 evenodd:{name:"Pair up",say:"0 2 4 6 8, even numbers pair up great",letters:[["E","Even","Everything pairs up. Ones digit 0, 2, 4, 6, or 8."],["O","Odd","One is left over. Ones digit 1, 3, 5, 7, or 9."]],chant:"0, 2, 4, 6, 8: even numbers pair up great. 1, 3, 5, 7, 9: odd ones leave one behind.",check:"Draw the dots in pairs."},
 decimal:{name:"Point under point",say:"Line up the decimal points",letters:[["1","Point under point","Write the decimal points in one straight column."],["2","Fill with zeros","Add zeros so both numbers have the same number of places."],["3","Work like whole numbers","Add, subtract, or compare place by place."],["4","Bring the point down","The decimal point stays in its column."]],chant:"Point under point, zeros fill in, work it out, point comes down.",check:"Estimate with whole numbers. Is the answer close?"},
 angle:{name:"Acute, Right, Obtuse",say:"A cute little angle, a right corner, a wide obtuse",letters:[["A","Acute","Less than 90 degrees. Small and pointy: a cute little angle."],["R","Right","Exactly 90 degrees. The corner of a paper."],["O","Obtuse","More than 90 degrees. Wide open."],["S","Straight","180 degrees. A straight line."]],chant:"Acute is cute and small, right is a corner, obtuse is wide.",check:"Compare it to a paper corner."},
 volume:{name:"Base, then stack",say:"Fill the bottom layer, then stack the layers",letters:[["B","Base","Length times width: the cubes in one layer."],["H","Height","How many layers."],["V","Volume","Base times height: V = l x w x h."]],chant:"Bottom layer, then stack. Length times width times height.",check:"Count one layer, then multiply by the layers."},
 factfamily:{name:"3 numbers, 4 facts",say:"Three numbers make four facts",letters:[["1","Find the three numbers","Two parts and a whole, or two factors and a product."],["2","Write the four facts","Two adds and two subtracts, or two times and two divides."],["3","Find the missing one","The unknown is whichever number is not written."]],chant:"Three numbers, four facts. Both sides of the equal sign must balance.",check:"Put the answer in and read the whole equation. Is it true?"},
 count:{name:"One touch, one number",say:"Touch one, say one",letters:[["1","Touch one","Touch each object once."],["2","Say one","Say one number for each touch."],["3","Last number","The last number you say is how many."]],chant:"One touch, one number. The last one tells how many.",check:"Count again the other direction. Same answer?"},
 compose:{name:"Make a ten",say:"Fill the frame first",letters:[["1","Start big","Start with the bigger number."],["2","Fill to ten","Take just enough from the other number to make 10."],["3","Add the rest","10 plus what is left."]],chant:"Fill the frame, then add the rest.",check:"Show it on a ten frame."},
 geometry:{name:"Sides and corners",say:"Count the sides, count the corners, say the name",letters:[["S","Sides","Count every straight side."],["C","Corners","Count every corner (vertex)."],["N","Name","3 is triangle, 4 is quadrilateral, 5 is pentagon, 6 is hexagon, 8 is octagon."]],chant:"Sides, corners, name.",check:"Trace each side with your finger as you count."},
 data:{name:"Title, key, numbers",say:"Read the title, read the key, then read the numbers",letters:[["T","Title","What is the graph about?"],["K","Key or scale","What does one picture or one line mean?"],["N","Numbers","Read each bar or row. Compare."]],chant:"Title, key, numbers.",check:"Point to the bar before you read its number."},
 coord:{name:"Run, then jump",say:"Run before you jump: x then y",letters:[["R","Run","The first number: go right along the x-axis."],["J","Jump","The second number: go up along the y-axis."],["O","Origin","Always start at (0, 0)."]],chant:"Run right, then jump up.",check:"Say the ordered pair as you move: right 3, up 5."},
