var FAMILY_OF={longdiv:"longdiv",divrep:"divide",decdiv:"decimal",remainder:"wordproblem",oops:"oops",round:"round",estimate:"estimate",wpadd:"wordproblem",wp2:"wordproblem",wpmd:"wordproblem",multistep:"wordproblem",measwp:"wordproblem",elapsed:"time",cmpnum:"compare",cmpsym:"compare",cmpsets:"compare",order:"compare",fraccmp:"fracsum",benchmark:"fracsum",addmulti:"regroupAdd",submulti:"regroupSub",adddec:"decimal",decimal:"decimal",decmult:"decimal",fracid:"fraction",unitfrac:"fraction",fracparts:"fraction",halves:"fraction",fracline:"fraction",fracshare:"fraction",fracdecomp:"fraction",fracsum:"fracsum",fracequiv:"fracequiv",fracdecline:"decimal",fracmult:"fracops",fracdiv:"fracops",mfacts:"mult",eqgroups:"mult",multmeaning:"mult",squares:"mult",x10:"pv",mult2x1:"multbig",multbig:"multbig",areamodel:"multbig",prime:"mult",divide:"divide",eqshares:"divide",pv:"pv",pvbig:"pv",tenmore:"pv",clock:"time",coinval:"money",coinname:"money",bills:"money",moneywrite:"money",save:"finance",budget:"finance",area:"areaperim",perim:"areaperim",paform:"areaperim",evenodd:"evenodd",angle:"angle",tri:"angle",geomid:"geometry",volume:"volume",unknown:"factfamily",unkfactor:"factfamily",eqtf:"factfamily",threeadd:"compose",count:"count",subit:"count",matchset:"count",countback:"count",onemore:"count",rote:"count",skip:"count",nline:"count",compose:"compose",decomp:"compose",maketen:"compose",add:"compose",sub:"compose",facts:"compose",mult10plus:"pv",shape2d:"geometry",shapeattr:"geometry",shape3d:"geometry",polygon:"geometry",solid:"geometry",graph:"data",pgraph:"data",graphwp:"data",freq:"data",stemleaf:"data",scatter:"data",pairs:"data",inout:"data",pattern:"data",coord:"coord",unitmeas:"measure",longer:"measure",holds:"measure",convert:"measure",bank:{wantneed:"finance",incomegift:"finance",jobskill:"finance",spendsave:"finance",fin2:"finance",fin3:"finance",fin4:"finance",fin5:"finance",payment:"finance",attrword:"measure",heavier:"measure",unitsize:"measure",capweight:"measure",sortcat:"data",defattr:"geometry",flatsolid:"geometry",hier:"geometry",quad:"geometry",symm:"geometry",ampm:"time",estim:"estimate",remain:"wordproblem",pattype:"data",coordattr:"coord",multcmp:"mult",ppty:"factfamily",joinsep:"wordproblem"}};
function familyFor(spec){return spec[0]==="bank"?(FAMILY_OF.bank[spec[1].bank]||null):(FAMILY_OF[spec[0]]||null);}
function mnemonicForDay(g,w,d){var specs=DATA[g].weeks[w-1].days[d-1];var fams=[];specs.forEach(function(sp){var f=familyFor(sp);if(f&&fams.indexOf(f)<0)fams.push(f);});return fams.map(function(f){return MNEMONICS[f];}).filter(Boolean);}

/* ===== step-by-step solution traces ===== */
function nums(q){return (q.q.replace(/<[^>]+>/g,"").replace(/,(?=\d{3}\b)/g,"").match(/-?\d+(\.\d+)?(\/\d+)?/g)||[]).map(function(x){return x.indexOf("/")>0?x:Number(x);});}
function mkStep(t,v){return {t:t,v:v||""};}
function colAdd(a,b){var A=String(a),B=String(b);var n=Math.max(A.length,B.length);A=Array(n-A.length+1).join("0")+A;B=Array(n-B.length+1).join("0")+B;var names=["ones","tens","hundreds","thousands","ten thousands"];var carry=0,steps=[mkStep("Line up the places: ones under ones, tens under tens.",stacked(a,b,"+"))],res="";for(var i=n-1;i>=0;i--){var s=Number(A[i])+Number(B[i])+carry;var p=names[n-1-i];var txt=p.charAt(0).toUpperCase()+p.slice(1)+": "+A[i]+" + "+B[i]+(carry?" + "+carry+" (carried)":"")+" = "+s+".";if(s>=10&&i>0){txt+=" Ten or more, go next door: write "+(s%10)+", carry 1.";carry=1;res=String(s%10)+res;}else{carry=0;res=String(s)+res;}steps.push(mkStep(txt));}steps.push(mkStep("Answer: "+fmt(a)+" + "+fmt(b)+" = "+fmt(a+b)+". Check with an estimate: about "+fmt(Math.round(a/10)*10)+" + "+fmt(Math.round(b/10)*10)+" = "+fmt(Math.round(a/10)*10+Math.round(b/10)*10)+"."));return steps;}
function colSub(a,b){var A=String(a).split("").map(Number),B=String(b).split("").map(Number);while(B.length<A.length)B.unshift(0);var names=["ones","tens","hundreds","thousands","ten thousands"];var steps=[mkStep("Line up the places. The bigger number goes on top.",stacked(a,b,"&minus;"))];for(var i=A.length-1;i>=0;i--){var p=names[A.length-1-i];var top=A[i],bot=B[i];var txt=p.charAt(0).toUpperCase()+p.slice(1)+": ";if(top>=bot){txt+=top+" &minus; "+bot+" = "+(top-bot)+". More on top, no need to stop.";}else{var j=i-1;while(j>=0&&A[j]===0)j--;if(j>=0){A[j]--;for(var k=j+1;k<i;k++)A[k]=9;top+=10;txt+="More on the floor, go next door: borrow a "+names[A.length-1-j].replace(/s$/,"")+". Now "+top+" &minus; "+bot+" = "+(top-bot)+".";}}steps.push(mkStep(txt));}steps.push(mkStep("Answer: "+fmt(a)+" &minus; "+fmt(b)+" = "+fmt(a-b)+". Check by adding: "+fmt(a-b)+" + "+fmt(b)+" = "+fmt(a)+"."));return steps;}
