function subjRoute(view){var subj=curSubj();if(subj==="math")return false;if(view==="plan"){renderPlanSubj();return true;}if(view==="teach"){renderTeachSubj();return true;}if(view==="asg"){renderAsgSubj();return true;}if(view==="act"){renderActSubj();return true;}return false;}
/* math auto-coverage: viewing a math day marks the week's codes covering; marking taught marks covered */
var _setDay=setDay;setDay=function(g,w,d,patch){_setDay(g,w,d,patch);if(curSubj()==="math"&&DATA[g]&&DATA[g].weeks[w-1]){var codes=DATA[g].weeks[w-1].teks;if(patch.viewed)covTouch("math",g,codes,1);if(patch.taught)covTouch("math",g,codes,2);}};
/* progress keys stay per grade; subject days share the key space only when the subject is math. Non-math subjects prefix. */
