var _migrating=false;var _SEQ=0;function nextId(){_SEQ=(_SEQ+1)%1000;return Date.now()*1000+_SEQ;}
function mkPerson(rec){return {id:"s"+Date.now().toString(36)+Math.floor(Math.random()*1e6).toString(36),first:(rec.first||"").trim(),last:(rec.last||"").trim(),grade:rec.grade||S.g,hrTeacher:(rec.hrTeacher||"").trim(),hrRoom:(rec.hrRoom||"").trim(),custom:rec.custom||{},created:today()};}
function peopleInit(){mem.people=mem.people||[];mem.fields=mem.fields||[];mem.sessions=mem.sessions||[];mem.snotes=mem.snotes||{};mem.done=mem.done||{};
  /* migrate the old per-grade name lists once */
  if(!_migrating&&!mem.people.length&&mem.students&&Object.keys(mem.students).length){_migrating=true;Object.keys(mem.students).forEach(function(g){(mem.students[g]||[]).forEach(function(n){var parts=String(n).trim().split(/\s+/);mem.people.push(mkPerson({first:parts[0]||n,last:parts.slice(1).join(" "),grade:g}));});});_migrating=false;save();}}
function fullName(p){return (p.first+" "+(p.last||"")).trim();}
function peopleAdd(rec){peopleInit();var p=mkPerson(rec);mem.fields.forEach(function(f){if(p.custom[f]===undefined)p.custom[f]="";});mem.people.push(p);syncRoster();save();return p;}
function peopleUpdate(id,patch){var p=personById(id);if(!p)return;Object.keys(patch).forEach(function(k){p[k]=patch[k];});syncRoster();save();}
function peopleRemove(id){mem.people=mem.people.filter(function(p){return p.id!==id;});syncRoster();save();}
function personById(id){peopleInit();return mem.people.filter(function(p){return p.id===id;})[0]||null;}
function personByName(name){peopleInit();return mem.people.filter(function(p){return fullName(p)===name;})[0]||null;}
function fieldAdd(label){peopleInit();label=String(label||"").trim();if(!label||mem.fields.indexOf(label)>=0)return;mem.fields.push(label);mem.people.forEach(function(p){if(p.custom[label]===undefined)p.custom[label]="";});save();}
function fieldRemove(label){peopleInit();mem.fields=mem.fields.filter(function(f){return f!==label;});mem.people.forEach(function(p){delete p.custom[label];});save();}
function syncRoster(){peopleInit();var by={};mem.people.forEach(function(p){(by[p.grade]=by[p.grade]||[]).push(fullName(p));});mem.students=by;}
function roster(g){peopleInit();syncRoster();return mem.students[g]||[];}
function allPeople(){peopleInit();return mem.people.slice().sort(function(a,b){return (a.last||"").localeCompare(b.last||"")||a.first.localeCompare(b.first);});}

/* ---- sessions: what happened with this student and when ---- */
function lessonCtx(){var subj=curSubj();if(subj==="math"){var w=DATA[S.g].weeks[S.w-1];return {subj:"math",g:S.g,w:S.w,d:S.d,unit:w.unit,codes:w.teks,ican:w.ican,focus:w.focus[S.d-1]};}var wk=subjWeek(subj,S.g,S.w);if(!wk)return null;var day=wk.days[S.d-1];return {subj:subj,g:S.g,w:S.w,d:S.d,unit:wk.unit,codes:[day.se.code].concat(day.practice?[day.practice.code]:[]),ican:"I can "+se1(day.se.text)+".",focus:day.focus};}
function logSession(kind,extra){peopleInit();if(!S.student)return null;var p=personByName(S.student);if(!p)return null;var c=lessonCtx();if(!c)return null;var key=p.id+"|"+today()+"|"+c.subj+"|"+c.g+"|"+c.w+"|"+c.d;var existing=null;if(kind==="viewed"){existing=mem.sessions.filter(function(s){return s.key===key;})[0];if(existing)return existing;}var s={id:nextId(),key:key,sid:p.id,date:today(),time:new Date().toTimeString().slice(0,5),kind:kind,subj:c.subj,g:c.g,w:c.w,d:c.d,unit:c.unit,codes:c.codes,ican:c.ican,focus:c.focus};if(extra)Object.keys(extra).forEach(function(k){s[k]=extra[k];});mem.sessions.push(s);save();return s;}
var _setResult=setResult;setResult=function(g,w,d,student,right){_setResult(g,w,d,student,right);if(student){var p=personByName(student);if(p){var c=lessonCtx();if(c&&c.g===g&&c.w===w&&c.d===d)logSession("exit",{score:right,of:3});}}};
function sessionsFor(sid){peopleInit();return mem.sessions.filter(function(s){return s.sid===sid;}).sort(function(a,b){return (b.date+b.time).localeCompare(a.date+a.time)||(b.id-a.id);});}
function lastHelped(sid){var ss=sessionsFor(sid);return ss.length?ss[0]:null;}
function lastHelp(sid){return sessionsFor(sid).filter(function(s){return s.kind==="help";})[0]||null;}
function snotesFor(sid){peopleInit();return (mem.snotes[sid]||[]).slice().sort(function(a,b){return b.date.localeCompare(a.date)||(b.id-a.id);});}
function snoteAdd(sid,text,label,tagLesson){peopleInit();var n={id:nextId(),date:today(),label:label||"Note",text:String(text||"").trim()};if(tagLesson){var c=lessonCtx();if(c){n.subj=c.subj;n.g=c.g;n.w=c.w;n.d=c.d;n.unit=c.unit;}}(mem.snotes[sid]=mem.snotes[sid]||[]).push(n);save();return n;}
function snoteRemove(sid,id){peopleInit();mem.snotes[sid]=(mem.snotes[sid]||[]).filter(function(n){return n.id!==id;});save();}
function doneKey(c){return c.subj+":"+c.g+"-"+c.w+"-"+c.d;}
function doneSet(sid,c,on,note){peopleInit();var d=mem.done[sid]=mem.done[sid]||{};var k=doneKey(c);if(on)d[k]={date:today(),subj:c.subj,g:c.g,w:c.w,d:c.d,unit:c.unit,codes:c.codes,ican:c.ican,note:note||""};else delete d[k];save();}
function doneFor(sid){peopleInit();var d=mem.done[sid]||{};return Object.keys(d).map(function(k){var x=d[k];x.key=k;return x;}).sort(function(a,b){return b.date.localeCompare(a.date);});}
function isDone(sid,c){peopleInit();return !!((mem.done[sid]||{})[doneKey(c)]);}
function studentCoverage(sid){var by={};sessionsFor(sid).concat(doneFor(sid)).forEach(function(s){var subj=s.subj;var b=by[subj]=by[subj]||{codes:{},lessons:{},first:s.date,last:s.date};(s.codes||[]).forEach(function(c){b.codes[c]=(b.codes[c]||0)+1;});b.lessons[s.g+"-"+s.w+"-"+s.d]=1;if(s.date<b.first)b.first=s.date;if(s.date>b.last)b.last=s.date;});return by;}
function studentCsv(p){var rows=[["Student",fullName(p)],["Grade",DATA[p.grade]?DATA[p.grade].label:p.grade],["Homeroom teacher",p.hrTeacher],["Homeroom",p.hrRoom]];mem.fields.forEach(function(f){rows.push([f,p.custom[f]||""]);});rows.push([]);rows.push(["Date","Time","Kind","Subject","Grade","Week","Day","Unit","Standards","Score","Note"]);sessionsFor(p.id).forEach(function(s){rows.push([s.date,s.time||"",s.kind,subjDef(s.subj).name,s.g,s.w,s.d,s.unit,(s.codes||[]).join(" "),s.score!==undefined?s.score+"/"+(s.of||3):"",s.note||""]);});rows.push([]);rows.push(["Completed coursework"]);doneFor(p.id).forEach(function(x){rows.push([x.date,"","complete",subjDef(x.subj).name,x.g,x.w,x.d,x.unit,(x.codes||[]).join(" "),"",x.note||""]);});rows.push([]);rows.push(["Notes"]);snotesFor(p.id).forEach(function(n){rows.push([n.date,"",n.label,n.subj?subjDef(n.subj).name:"",n.g||"",n.w||"",n.d||"",n.unit||"","","",n.text]);});return rows.map(function(r){return r.map(function(c){return '"'+String(c===undefined?"":c).replace(/"/g,'""')+'"';}).join(",");}).join("\n");}

/* ---- Teach view helper: who am I helping right now ---- */
function helpingCard(){peopleInit();var box=el("div","card helping");var people=allPeople();var c=lessonCtx();function draw(){box.innerHTML='<div class="helphead"><h2 style="margin:0">Who am I helping?</h2><div class="meta">Pick the student and this lesson is logged to their record. Scores, notes, and completion attach to them.</div></div>';var row=el("div","form");var sel=el("select");sel.className="studsel";sel.innerHTML='<option value="">Whole class / no student</option>'+people.map(function(p){return '<option value="'+esc(fullName(p))+'"'+(fullName(p)===S.student?" selected":"")+'>'+esc(fullName(p))+' ('+(DATA[p.grade]?DATA[p.grade].label:p.grade)+(p.hrRoom?', room '+esc(p.hrRoom):'')+')</option>';}).join("");sel.setAttribute("aria-label","Student being helped");sel.addEventListener("change",function(){S.student=sel.value;if(S.student)logSession("viewed");draw();});var d1=el("div");d1.innerHTML='<label>Student</label>';d1.appendChild(sel);row.appendChild(d1);box.appendChild(row);
    if(!people.length){var np=el("p","meta","No students yet. Add them in the <b>Students</b> tab (first and last name, homeroom, any labels you need).");box.appendChild(np);return;}
    if(!S.student)return;var p=personByName(S.student);if(!p)return;var last=lastHelped(p.id);var info=el("div","helpinfo");info.innerHTML='<div><b>'+esc(fullName(p))+'</b> &middot; '+(DATA[p.grade]?DATA[p.grade].label:p.grade)+(p.hrTeacher?' &middot; homeroom '+esc(p.hrTeacher):'')+(p.hrRoom?' room '+esc(p.hrRoom):'')+mem.fields.map(function(f){return p.custom[f]?' &middot; '+esc(f)+': '+esc(p.custom[f]):'';}).join("")+'</div><div class="meta">'+(last?'Last helped '+esc(last.date)+' '+esc(last.time||"")+': '+esc(subjDef(last.subj).name)+', '+esc(last.unit)+' (day '+last.d+')'+(last.score!==undefined?', exit '+last.score+'/'+(last.of||3):'')+(last.note?' &middot; "'+esc(last.note)+'"':''):'No sessions logged yet. This one is being logged now.')+'</div>';box.appendChild(info);
    var act=el("div","helpact");act.innerHTML='<label class="meta">What did you help with? (one line, saved to '+esc(p.first)+"'s record)"+'</label><input type="text" class="helpnote" placeholder="e.g., needed the ten frame to regroup; got 2 of 3 alone"><div class="btn-row"><button class="btn sm loghelp">Log help</button><button class="btn quiet sm mkdone">'+(c&&isDone(p.id,c)?"Complete for "+esc(p.first)+" (undo)":"Mark complete for "+esc(p.first))+'</button>'+(c&&dayRec(c.g,c.w,c.d).taught?'<span class="meta">Class: marked taught &#10003;</span>':'')+'<button class="btn quiet sm openprof">Open '+esc(p.first)+"'s record</button></div>";box.appendChild(act);
    act.querySelector(".loghelp").addEventListener("click",function(){var t=act.querySelector(".helpnote").value.trim();if(!t){alert("Type one line about the help given.");return;}logSession("help",{note:t});snoteAdd(p.id,t,"Help given",true);act.querySelector(".helpnote").value="";draw();});
    act.querySelector(".mkdone").addEventListener("click",function(){if(!c)return;var on=!isDone(p.id,c);doneSet(p.id,c,on);if(on)logSession("viewed");draw();var mb=document.getElementById("markTaught")||document.querySelector(".markbtn");if(mb&&on&&!dayRec(c.g,c.w,c.d).taught){mb.textContent="Marked complete for "+p.first+"; click to also mark the class day taught";}});act.querySelector(".openprof").addEventListener("click",function(){S.view="students";S.sid=p.id;render();window.scrollTo(0,0);});}
  draw();return box;}

/* ---- STUDENTS view ---- */
function personForm(p,onSave){var f=el("div","personform");var isNew=!p;p=p||{first:"",last:"",grade:S.g,hrTeacher:"",hrRoom:"",custom:{}};f.innerHTML='<div class="form"><div><label>First name</label><input type="text" class="pf-first" value="'+esc(p.first)+'"></div><div><label>Last name</label><input type="text" class="pf-last" value="'+esc(p.last)+'"></div><div><label>Grade</label><select class="pf-grade">'+ORDER.map(function(g){return '<option value="'+g+'"'+(g===p.grade?" selected":"")+'>'+DATA[g].label+'</option>';}).join("")+'</select></div><div><label>Homeroom teacher</label><input type="text" class="pf-hrt" value="'+esc(p.hrTeacher)+'"></div><div><label>Homeroom number</label><input type="text" class="pf-hrr" value="'+esc(p.hrRoom)+'"></div>'+mem.fields.map(function(lbl){return '<div><label>'+esc(lbl)+'</label><input type="text" class="pf-custom" data-f="'+esc(lbl)+'" value="'+esc(p.custom[lbl]||"")+'"></div>';}).join("")+'</div><div class="btn-row"><button class="btn sm pf-save">'+(isNew?"Add student":"Save changes")+'</button>'+(isNew?'':'<button class="btn quiet sm pf-del">Remove student</button>')+'</div>';
  f.querySelector(".pf-save").addEventListener("click",function(){var rec={first:f.querySelector(".pf-first").value,last:f.querySelector(".pf-last").value,grade:f.querySelector(".pf-grade").value,hrTeacher:f.querySelector(".pf-hrt").value,hrRoom:f.querySelector(".pf-hrr").value,custom:{}};Array.prototype.forEach.call(f.querySelectorAll(".pf-custom"),function(i){rec.custom[i.getAttribute("data-f")]=i.value;});if(!rec.first.trim()){alert("First name is required.");return;}if(isNew){var np=peopleAdd(rec);onSave(np);}else{peopleUpdate(p.id,rec);onSave(personById(p.id));}});
  var del=f.querySelector(".pf-del");if(del)del.addEventListener("click",function(){if(!confirm("Remove "+fullName(p)+"? Their sessions, notes, and completed work stay in the export but will no longer show here."))return;peopleRemove(p.id);S.sid=null;renderStudents();});return f;}
function renderStudents(){peopleInit();var main=document.getElementById("main");main.innerHTML="";if(S.sid&&personById(S.sid)){renderStudentProfile(personById(S.sid));return;}
  var head=el("div","card");head.innerHTML='<h2>Students</h2><p>Look a student up in seconds: where they were helped last, notes, and what they have completed across every subject. Nothing here needs a login; it lives with your class data.</p><input type="search" class="search" id="stuSearch" placeholder="Search by name, homeroom, room, or any label" autofocus>';main.appendChild(head);
  var list=el("div","stulist");main.appendChild(list);
  function draw(f){list.innerHTML="";f=(f||"").toLowerCase();var people=allPeople().filter(function(p){if(!f)return true;var hay=(fullName(p)+" "+p.hrTeacher+" "+p.hrRoom+" "+(DATA[p.grade]?DATA[p.grade].label:p.grade)+" "+mem.fields.map(function(k){return p.custom[k]||"";}).join(" ")).toLowerCase();return hay.indexOf(f)>=0;});if(!people.length){list.appendChild(el("div","card",allPeople().length?"<p>No student matches that search.</p>":"<p>No students yet. Add the first one below.</p>"));}
    people.forEach(function(p){var last=lastHelped(p.id);var done=doneFor(p.id).length;var c=el("button","card stucard");c.innerHTML='<div class="stuname">'+esc(fullName(p))+'</div><div class="meta">'+(DATA[p.grade]?DATA[p.grade].label:p.grade)+(p.hrTeacher?' &middot; '+esc(p.hrTeacher):'')+(p.hrRoom?' &middot; room '+esc(p.hrRoom):'')+'</div><div class="stulast">'+(last?'<b>Last lesson:</b> '+esc(last.date)+' &middot; '+esc(subjDef(last.subj).name)+' &middot; '+esc(last.unit):'<span class="meta">No sessions yet</span>')+(function(){var h=lastHelp(p.id);return h?'<br><b>Last help:</b> '+esc(h.date)+' &middot; "'+esc(h.note)+'"':'';})()+'</div><div class="meta">'+done+' lesson'+(done===1?'':'s')+' completed &middot; '+snotesFor(p.id).length+' note'+(snotesFor(p.id).length===1?'':'s')+'</div>';c.addEventListener("click",function(){S.sid=p.id;renderStudents();window.scrollTo(0,0);});list.appendChild(c);});}
  draw("");head.querySelector("#stuSearch").addEventListener("input",function(e){draw(e.target.value);});
  var add=el("div","card");add.innerHTML='<h2>Add a student</h2>';add.appendChild(personForm(null,function(p){S.sid=p.id;renderStudents();}));main.appendChild(add);
  var lab=el("div","card");lab.innerHTML='<h2>Labels for every student</h2><p class="meta">Add any label you need (case manager, accommodations, bus, medication time, reading level). It appears on every student\'s record and on the add form, now and for students you add later.</p><div class="chips">'+mem.fields.map(function(f){return '<span class="chip">'+esc(f)+' <button class="ndel" data-f="'+esc(f)+'" title="Remove this label">&times;</button></span>';}).join("")+(mem.fields.length?'':'<span class="meta">No custom labels yet.</span>')+'</div><div class="form" style="margin-top:.5rem"><div><label>New label</label><input type="text" id="newField" placeholder="e.g., Case manager"></div><div><label>&nbsp;</label><button class="btn sm" id="addField">Add label</button></div></div>';
  lab.querySelector("#addField").addEventListener("click",function(){fieldAdd(lab.querySelector("#newField").value);renderStudents();});Array.prototype.forEach.call(lab.querySelectorAll(".ndel"),function(b){b.addEventListener("click",function(){if(!confirm("Remove the label \""+b.getAttribute("data-f")+"\" from every student?"))return;fieldRemove(b.getAttribute("data-f"));renderStudents();});});main.appendChild(lab);}
function renderStudentProfile(p){var main=document.getElementById("main");var last=lastHelped(p.id);var bar=el("div","btn-row noprint");var back=el("button","btn quiet sm","&larr; All students");back.addEventListener("click",function(){S.sid=null;renderStudents();});bar.appendChild(back);var csv=el("button","btn quiet sm","Export this record (CSV)");csv.addEventListener("click",function(){download(slug(fullName(p))+"-record-"+today()+".csv",studentCsv(p),"text/csv");});bar.appendChild(csv);var pr=el("button","btn quiet sm","Print this record");pr.addEventListener("click",function(){window.print();});bar.appendChild(pr);main.appendChild(bar);
  main.appendChild(printHead(fullName(p)+" record"));
  var head=el("div","card hero stuhero");head.innerHTML='<div><div class="eyebrow">Student record</div><h1>'+esc(fullName(p))+'</h1><div class="chips"><span class="chip">'+(DATA[p.grade]?DATA[p.grade].label:esc(p.grade))+'</span>'+(p.hrTeacher?'<span class="chip">Homeroom: '+esc(p.hrTeacher)+'</span>':'')+(p.hrRoom?'<span class="chip">Room '+esc(p.hrRoom)+'</span>':'')+mem.fields.map(function(f){return p.custom[f]?'<span class="chip">'+esc(f)+': '+esc(p.custom[f])+'</span>':'';}).join("")+'</div></div>';main.appendChild(head);
  var lh=el("div","card lasthelp");lh.innerHTML='<h2>Where we left off</h2>'+(last?'<div class="ican">'+esc(last.ican)+'</div><p><b>'+esc(last.date)+' '+esc(last.time||"")+'</b> &middot; '+esc(subjDef(last.subj).name)+' &middot; '+(DATA[last.g]?DATA[last.g].label:last.g)+' &middot; Week '+last.w+', Day '+last.d+' &middot; '+esc(last.unit)+'</p><p class="meta">'+esc(last.focus||"")+' &middot; standards: '+(last.codes||[]).join(", ")+(last.score!==undefined?' &middot; exit ticket '+last.score+'/'+(last.of||3):'')+'</p>'+(function(){var h=lastHelp(p.id);return h?'<div class="learnbox"><b>Last help given</b> ('+esc(h.date)+' '+esc(h.time||"")+', '+esc(subjDef(h.subj).name)+', '+esc(h.unit)+'): '+esc(h.note)+'</div>':'';})():'<p class="meta">No sessions yet. Pick this student under "Who am I helping?" in any Teach view and the lesson is logged here.</p>');if(last){var rb=el("button","btn","Resume this lesson with "+esc(p.first));rb.addEventListener("click",function(){S.subj=last.subj;S.g=last.g;S.w=last.w;S.d=last.d;S.student=fullName(p);S.view="teach";render();window.scrollTo(0,0);});lh.appendChild(rb);}main.appendChild(lh);
  var nt=el("div","card");nt.innerHTML='<h2>Notes</h2>';var nform=el("div","noteform noprint");nform.innerHTML='<div class="form"><div><label>Label</label><select class="nsel"><option>Note</option><option>Help given</option><option>Strategy that worked</option><option>Accommodation</option><option>Behavior</option><option>Parent contact</option><option>IEP goal</option></select></div><div style="grid-column:span 2"><label>Note</label><input type="text" class="ntxt" placeholder="What happened, what worked, what to try next"></div><div><label>&nbsp;</label><button class="btn sm nsave">Add note</button></div></div>';nform.querySelector(".nsave").addEventListener("click",function(){var t=nform.querySelector(".ntxt").value.trim();if(!t)return;snoteAdd(p.id,t,nform.querySelector(".nsel").value,false);renderStudents();});nt.appendChild(nform);var nl=el("div","notelist");var notes=snotesFor(p.id);if(!notes.length)nl.appendChild(el("p","meta","No notes yet."));notes.forEach(function(n){var it=el("div","noteit");it.innerHTML='<span class="nlabel">'+esc(n.label)+'</span><span class="ntext">'+esc(n.text)+(n.unit?' <span class="meta">('+esc(subjDef(n.subj).name)+', '+esc(n.unit)+', day '+n.d+')</span>':'')+'</span><span class="meta ndate">'+esc(n.date)+'</span><button class="ndel noprint" title="Delete">&times;</button>';it.querySelector(".ndel").addEventListener("click",function(){if(!confirm("Delete this note?"))return;snoteRemove(p.id,n.id);renderStudents();});nl.appendChild(it);});nt.appendChild(nl);main.appendChild(nt);
  var dn=el("div","card");var done=doneFor(p.id);dn.innerHTML='<h2>Completed coursework ('+done.length+')</h2><p class="meta">Lessons you marked complete for '+esc(p.first)+' specifically, from any subject. Mark or unmark in the Teach view ("Mark this lesson complete") or below.</p>'+(done.length?'<table class="tk"><tr><th>Date</th><th>Subject</th><th>Lesson</th><th>Standards</th><th class="noprint"></th></tr>'+done.map(function(x){return '<tr><td>'+esc(x.date)+'</td><td>'+esc(subjDef(x.subj).name)+' '+(DATA[x.g]?DATA[x.g].label:x.g)+'</td><td><b>'+esc(x.unit)+'</b><div class="meta">Week '+x.w+', Day '+x.d+' &middot; '+esc(x.ican||"")+'</div></td><td>'+(x.codes||[]).join(", ")+'</td><td class="noprint"><button class="hintbtn undone" data-k="'+esc(x.key)+'">unmark</button></td></tr>';}).join("")+'</table>':'<p class="meta">Nothing marked complete yet.</p>');Array.prototype.forEach.call(dn.querySelectorAll(".undone"),function(b){b.addEventListener("click",function(){delete mem.done[p.id][b.getAttribute("data-k")];save();renderStudents();});});main.appendChild(dn);
  var ss=el("div","card");var sessions=sessionsFor(p.id);ss.innerHTML='<h2>Sessions ('+sessions.length+')</h2><p class="meta">Every lesson opened with '+esc(p.first)+' selected, every exit ticket, and every logged help.</p>'+(sessions.length?'<table class="tk"><tr><th>When</th><th>What</th><th>Lesson</th><th>Standards</th><th>Result</th></tr>'+sessions.map(function(s){return '<tr><td>'+esc(s.date)+'<div class="meta">'+esc(s.time||"")+'</div></td><td>'+(s.kind==="exit"?"Exit ticket":s.kind==="help"?"Help given":"Lesson opened")+'</td><td>'+esc(subjDef(s.subj).name)+' '+(DATA[s.g]?DATA[s.g].label:s.g)+': <b>'+esc(s.unit)+'</b><div class="meta">Week '+s.w+', Day '+s.d+'</div></td><td>'+(s.codes||[]).join(", ")+'</td><td>'+(s.score!==undefined?'<b>'+s.score+'/'+(s.of||3)+'</b>':s.note?esc(s.note):'')+'</td></tr>';}).join("")+'</table>':'<p class="meta">No sessions yet.</p>');main.appendChild(ss);
  var cov=studentCoverage(p.id);var cv=el("div","card");cv.innerHTML='<h2>Standards this student has worked on</h2>'+(Object.keys(cov).length?Object.keys(cov).map(function(subj){var b=cov[subj];var codes=Object.keys(b.codes).sort();return '<h3>'+esc(subjDef(subj).name)+' <span class="meta">'+Object.keys(b.lessons).length+' lesson'+(Object.keys(b.lessons).length===1?'':'s')+', '+esc(b.first)+' to '+esc(b.last)+'</span></h3><div class="chips">'+codes.map(function(c){return '<span class="chip" title="'+b.codes[c]+' time'+(b.codes[c]===1?'':'s')+'">'+c+' <small>&times;'+b.codes[c]+'</small></span>';}).join("")+'</div>';}).join(""):'<p class="meta">Nothing yet.</p>');main.appendChild(cv);
  var ed=el("div","card noprint");ed.innerHTML='<h2>Edit details</h2>';ed.appendChild(personForm(p,function(){renderStudents();}));main.appendChild(ed);}

/* ---- current student: header pill, grade lock, taught<->complete sync ---- */
function curStudent(){return S.student?personByName(S.student):null;}
function studentGrade(){var p=curStudent();return p?p.grade:null;}
function applyStudentLock(){var p=curStudent();if(p&&DATA[p.grade]&&S.g!==p.grade){S.g=p.grade;S.w=Math.min(S.w||1,36);}var gp=document.getElementById("gpick");if(gp){Array.prototype.forEach.call(gp.querySelectorAll(".gbtn"),function(b){var k=b.id.replace("g-","");b.style.display=(p&&k!==p.grade)?"none":"";b.title=p&&k===p.grade?"Locked to "+fullName(p)+"'s grade. Clear the student to see all grades.":"";});}}
function markTaughtAndComplete(){var c=lessonCtx();if(!c)return;setDay(S.g,S.w,S.d,{taught:1});if(c.subj!=="math"&&typeof covTouch==="function")covTouch(c.subj,c.g,c.codes,2);var p=curStudent();if(p){doneSet(p.id,c,true);logSession("viewed");}}
function studentPill(){peopleInit();var host=document.getElementById("stupill");if(!host)return;host.innerHTML="";var people=allPeople();var lab=el("span","glabel","Student:");host.appendChild(lab);var sel=el("select");sel.id="stusel";sel.setAttribute("aria-label","Student you are helping");sel.innerHTML='<option value="">No student (show everything)</option>'+people.map(function(p){return '<option value="'+esc(fullName(p))+'"'+(fullName(p)===S.student?" selected":"")+'>'+esc(fullName(p))+' ('+(DATA[p.grade]?DATA[p.grade].label:p.grade)+')</option>';}).join("");sel.addEventListener("change",function(){S.student=sel.value;var p=curStudent();if(p){S.g=p.grade;if(S.w>36)S.w=1;}render();});host.appendChild(sel);var p=curStudent();if(p){var tag=el("span","stutag","<b>Helping "+esc(fullName(p))+"</b> &middot; "+(DATA[p.grade]?DATA[p.grade].label:esc(p.grade))+(p.hrRoom?" &middot; room "+esc(p.hrRoom):"")+(p.hrTeacher?" &middot; "+esc(p.hrTeacher):""));var open=el("button","btn quiet sm","Record");open.addEventListener("click",function(){S.view="students";S.sid=p.id;render();window.scrollTo(0,0);});var clr=el("button","btn quiet sm","Clear");clr.title="Stop helping this student and show all grades";clr.addEventListener("click",function(){S.student="";render();});host.appendChild(tag);host.appendChild(open);host.appendChild(clr);}}

